// src/lib/mcp/data.ts
var SPORTS = ["cricket", "nfl", "soccer", "basketball", "mlb", "nhl"];
var SPORT_DATA = {
  cricket: { label: "Cricket", players, teams },
  nfl: { label: "NFL (American Football)", players: nflPlayers, teams: nflTeams },
  soccer: { label: "Soccer (Football)", players: soccerPlayers, teams: soccerTeams },
  basketball: { label: "Basketball (NBA)", players: basketballPlayers, teams: basketballTeams },
  mlb: { label: "Baseball (MLB)", players: mlbPlayers, teams: mlbTeams },
  nhl: { label: "Ice Hockey (NHL)", players: nhlPlayers, teams: nhlTeams }
};
function allPlayers() {
  return SPORTS.flatMap(
    (sport) => SPORT_DATA[sport].players.map((player) => ({ sport, player }))
  );
}

// src/lib/mcp/tools/list-sports.ts
var list_sports_default = defineTool({
  name: "list_sports",
  title: "List sports",
  description: "List every sport covered by this app, with its team names and how many players are available.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: () => {
    const sports = SPORTS.map((key) => ({
      sport: key,
      label: SPORT_DATA[key].label,
      playerCount: SPORT_DATA[key].players.length,
      teams: SPORT_DATA[key].teams
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(sports, null, 2) }],
      structuredContent: { sports }
    };
  }
});

// src/lib/mcp/tools/list-players.ts
import { defineTool as defineTool2, ToolError } from "npm:@lovable.dev/mcp-js@0.26.3";
import { z } from "npm:zod@^3.25.76";
var list_players_default = defineTool2({
  name: "list_players",
  title: "List players",
  description: "List players for a sport, optionally filtered by team. Returns id, name, team and role/position.",
  inputSchema: {
    sport: z.enum(SPORTS).describe("Sport key, e.g. cricket, nfl, soccer, basketball, mlb, nhl."),
    team: z.string().trim().min(1).optional().describe("Optional exact team name to filter by.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ sport, team }) => {
    const entry = SPORT_DATA[sport];
    if (team && !entry.teams.some((t) => t.toLowerCase() === team.toLowerCase())) {
      throw new ToolError(
        `Unknown team "${team}" for ${entry.label}. Available: ${entry.teams.join(", ")}`
      );
    }
    const list = entry.players.filter((p) => !team || p.team.toLowerCase() === team.toLowerCase()).map((p) => ({
      id: p.id,
      name: p.name,
      team: p.team,
      role: p.role ?? p.position ?? null
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(list, null, 2) }],
      structuredContent: { sport, players: list }
    };
  }
});

// src/lib/mcp/tools/search-players.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.3";
import { z as z2 } from "npm:zod@^3.25.76";
var search_players_default = defineTool3({
  name: "search_players",
  title: "Search players",
  description: "Search all sports for players by name, team, or role/position. Returns matching players with their sport.",
  inputSchema: {
    query: z2.string().trim().min(1).describe("Free-text search over player name, team and role."),
    limit: z2.number().int().min(1).max(50).optional().describe("Max results (default 20).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, limit }) => {
    const q = query.toLowerCase();
    const results = allPlayers().filter(
      ({ player }) => [player.name, player.team, player.role ?? player.position ?? ""].join(" ").toLowerCase().includes(q)
    ).slice(0, limit ?? 20).map(({ sport, player }) => ({
      sport,
      id: player.id,
      name: player.name,
      team: player.team,
      role: player.role ?? player.position ?? null
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(results, null, 2) }],
      structuredContent: { query, results }
    };
  }
});

// src/lib/mcp/tools/get-player-stats.ts
import { defineTool as defineTool4, ToolError as ToolError2 } from "npm:@lovable.dev/mcp-js@0.26.3";
import { z as z3 } from "npm:zod@^3.25.76";
var get_player_stats_default = defineTool4({
  name: "get_player_stats",
  title: "Get player stats",
  description: "Get the full stat sheet for one player by id (e.g. virat-kohli) or by name. Searches every sport.",
  inputSchema: {
    query: z3.string().trim().min(1).describe("Player id or player name.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query }) => {
    const q = query.toLowerCase();
    const entries = allPlayers();
    const match = entries.find((e) => e.player.id.toLowerCase() === q) ?? entries.find((e) => e.player.name.toLowerCase() === q) ?? entries.find((e) => e.player.name.toLowerCase().includes(q));
    if (!match) throw new ToolError2(`No player found matching "${query}".`);
    const { sport, player } = match;
    const result = {
      sport,
      id: player.id,
      name: player.name,
      team: player.team,
      role: player.role ?? player.position ?? null,
      stats: player.stats
    };
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
      structuredContent: result
    };
  }
});

// src/lib/mcp/tools/compare-players.ts
import { defineTool as defineTool5, ToolError as ToolError3 } from "npm:@lovable.dev/mcp-js@0.26.3";
import { z as z4 } from "npm:zod@^3.25.76";
var compare_players_default = defineTool5({
  name: "compare_players",
  title: "Compare players",
  description: "Compare the stat sheets of two or more players from the same sport, side by side.",
  inputSchema: {
    sport: z4.enum(SPORTS).describe("Sport the players belong to."),
    players: z4.array(z4.string().trim().min(1)).min(2).max(5).describe("Two to five player ids or names from that sport.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ sport, players: players2 }) => {
    const pool = allPlayers().filter((e) => e.sport === sport);
    const resolved = players2.map((query) => {
      const q = query.toLowerCase();
      const match = pool.find((e) => e.player.id.toLowerCase() === q) ?? pool.find((e) => e.player.name.toLowerCase() === q) ?? pool.find((e) => e.player.name.toLowerCase().includes(q));
      if (!match) {
        throw new ToolError3(`No ${SPORT_DATA[sport].label} player found matching "${query}".`);
      }
      const { player } = match;
      return {
        id: player.id,
        name: player.name,
        team: player.team,
        role: player.role ?? player.position ?? null,
        stats: player.stats
      };
    });
    return {
      content: [{ type: "text", text: JSON.stringify(resolved, null, 2) }],
      structuredContent: { sport, players: resolved }
    };
  }
});

