// src/lib/mcp/supabase.ts
import { createClient } from "npm:@supabase/supabase-js@^2.111.0";
function runtimeEnv(name) {
  const runtime = globalThis;
  return runtime.Deno?.env?.get?.(name) ?? runtime.process?.env?.[name];
}
function configuredEnv(names) {
  for (const name of names) {
    const value = runtimeEnv(name)?.trim();
    if (value) return value;
  }
  return void 0;
}
function supabaseProjectUrl() {
  const url = configuredEnv(["SUPABASE_URL", "VITE_SUPABASE_URL"]);
  if (!url) throw new Error("SUPABASE_URL (or VITE_SUPABASE_URL) is required");
  return url;
}
function supabasePublishableKey() {
  const direct = configuredEnv([
    "SUPABASE_PUBLISHABLE_KEY",
    "VITE_SUPABASE_PUBLISHABLE_KEY"
  ]);
  if (direct) return direct;
  const keyset = runtimeEnv("SUPABASE_PUBLISHABLE_KEYS");
  if (keyset) {
    try {
      const parsed = JSON.parse(keyset);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        const keys = parsed;
        const key = [keys.default, ...Object.values(keys)].find((v) => typeof v === "string" && v.trim().startsWith("sb_publishable_"))?.trim();
        if (key) return key;
      }
    } catch {
    }
  }
  const legacy = configuredEnv(["SUPABASE_ANON_KEY", "VITE_SUPABASE_ANON_KEY"]);
  if (legacy) return legacy;
  throw new Error("SUPABASE_PUBLISHABLE_KEY, SUPABASE_PUBLISHABLE_KEYS, or SUPABASE_ANON_KEY is required");
}
function supabaseAnon() {
  return createClient(supabaseProjectUrl(), supabasePublishableKey(), {
    auth: { persistSession: false, autoRefreshToken: false }
  });
}

// src/lib/mcp/tools/update-player-stats.ts
var update_player_stats_default = defineTool6({
  name: "update_player_stats",
  title: "Update player stats",
  description: "Update a player's stats, current team, portrait or display name. Stat fields are merged into the player's existing stat sheet, so you can send only the fields that changed. The update is stored as an override and immediately replaces the built-in values everywhere in the app.",
  inputSchema: {
    player: z5.string().trim().min(1).describe("Player id (e.g. virat-kohli) or full player name."),
    sport: z5.enum(SPORTS).optional().describe("Optional sport hint, useful when the same name exists in several sports."),
    stats: z5.record(z5.string(), z5.unknown()).optional().describe("Stat fields to change, using the same field names the read tools return."),
    team: z5.string().trim().min(1).optional().describe("New current team or club."),
    name: z5.string().trim().min(1).optional().describe("Corrected display name."),
    image: z5.string().url().optional().describe("Portrait image URL (Wikimedia Commons, face-forward crop)."),
    source: z5.string().trim().min(1).optional().describe("Where the new numbers came from, e.g. 'Baseball-Reference, 2025 season end'.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: true, openWorldHint: false },
  handler: async ({ player, sport, stats, team, name, image, source }) => {
    if (!stats && !team && !name && !image) {
      throw new ToolError4("Provide at least one of: stats, team, name, image.");
    }
    const q = player.toLowerCase();
    const pool = allPlayers().filter((e) => !sport || e.sport === sport);
    const match = pool.find((e) => e.player.id.toLowerCase() === q) ?? pool.find((e) => e.player.name.toLowerCase() === q) ?? pool.find((e) => e.player.name.toLowerCase().includes(q));
    if (!match) throw new ToolError4(`No player found matching "${player}".`);
    const supabase = supabaseAnon();
    const { data: existing, error: readError } = await supabase.from("player_overrides").select("name, team, image, stats").eq("sport", match.sport).eq("player_id", match.player.id).maybeSingle();
    if (readError) throw new ToolError4(readError.message);
    const currentStats = {
      ...match.player.stats ?? {},
      ...existing?.stats ?? {}
    };
    const mergedStats = stats ? { ...currentStats, ...stats } : currentStats;
    const row = {
      sport: match.sport,
      player_id: match.player.id,
      name: name ?? existing?.name ?? null,
      team: team ?? existing?.team ?? null,
      image: image ?? existing?.image ?? null,
      stats: mergedStats,
      source: source ?? null,
      updated_at: (/* @__PURE__ */ new Date()).toISOString()
    };
    const { error } = await supabase.from("player_overrides").upsert(row, { onConflict: "sport,player_id" });
    if (error) throw new ToolError4(error.message);
    const result = {
      sport: match.sport,
      id: match.player.id,
      name: row.name ?? match.player.name,
      team: row.team ?? match.player.team,
      image: row.image ?? match.player.image ?? null,
      stats: mergedStats,
      source: row.source,
      updated_at: row.updated_at
    };
    return {
      content: [
        {
          type: "text",
          text: `Updated ${result.name} (${result.sport}).
${JSON.stringify(result, null, 2)}`
        }
      ],
      structuredContent: { player: result }
    };
  }
});

// src/lib/mcp/tools/list-player-updates.ts
import { defineTool as defineTool7, ToolError as ToolError5 } from "npm:@lovable.dev/mcp-js@0.26.3";
import { z as z6 } from "npm:zod@^3.25.76";
var list_player_updates_default = defineTool7({
  name: "list_player_updates",
  title: "List player updates",
  description: "List the stat updates that have been applied on top of the built-in data, newest first. Use it to see what has already been refreshed and when.",
  inputSchema: {
    sport: z6.enum(SPORTS).optional().describe("Limit to one sport."),
    limit: z6.number().int().min(1).max(200).default(50).describe("Maximum rows to return.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ sport, limit }) => {
    const supabase = supabaseAnon();
    let query = supabase.from("player_overrides").select("sport, player_id, name, team, image, stats, source, updated_at").order("updated_at", { ascending: false }).limit(limit ?? 50);
    if (sport) query = query.eq("sport", sport);
    const { data, error } = await query;
    if (error) throw new ToolError5(error.message);
    const updates = (data ?? []).map((row) => ({
      sport: row.sport,
      id: row.player_id,
      name: row.name,
      team: row.team,
      image: row.image,
      stats: row.stats,
      source: row.source,
      updated_at: row.updated_at
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(updates, null, 2) }],
      structuredContent: { count: updates.length, updates }
    };
  }
});

// src/lib/mcp/tools/revert-player-update.ts
import { defineTool as defineTool8, ToolError as ToolError6 } from "npm:@lovable.dev/mcp-js@0.26.3";
import { z as z7 } from "npm:zod@^3.25.76";
var revert_player_update_default = defineTool8({
  name: "revert_player_update",
  title: "Revert player update",
  description: "Remove a previously applied update for one player, restoring the built-in stat sheet, team and portrait.",
  inputSchema: {
    sport: z7.enum(SPORTS).describe("Sport the player belongs to."),
    player_id: z7.string().trim().min(1).describe("Player id, e.g. virat-kohli.")
  },
  annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ sport, player_id }) => {
    const supabase = supabaseAnon();
    const { data, error } = await supabase.from("player_overrides").delete().eq("sport", sport).eq("player_id", player_id).select("player_id");
    if (error) throw new ToolError6(error.message);
    const removed = (data ?? []).length > 0;
    return {
      content: [
        {
          type: "text",
          text: removed ? `Reverted ${player_id} (${sport}) to the built-in data.` : `No stored update found for ${player_id} (${sport}).`
        }
      ],
      structuredContent: { reverted: removed, sport, player_id }
    };
  }
});

